    load_kwargs.setdefault("low_cpu_mem_usage", True)
    if coerced.trust_remote_code:
        load_kwargs.setdefault("trust_remote_code", True)

    _ensure_bf16_capability(
        coerced.dtype,
        dtype,
        device,
        require_capability=coerced.bf16_require_capability,
    )

